(()=>{const cls=document.getElementById('class');const hero=document.getElementById('heroClass');const live=document.getElementById('liveClass');if(!cls)return;const sync=()=>{if(hero)hero.textContent=cls.value;if(live)live.textContent=cls.value};cls.addEventListener('change',sync);sync();Promise.all([fetch('/api/classes').then(r=>r.json()),fetch('/api/notices?class_code='+encodeURIComponent(cls.value)+'&limit=1').then(r=>r.json())]).then(([classes,notices])=>{const mc=document.getElementById('metricClasses'),mn=document.getElementById('metricNotices');if(mc)mc.textContent=Array.isArray(classes)?classes.length:'—';if(mn)mn.textContent=typeof notices.total==='number'?notices.total:Array.isArray(notices)?notices.length:'—'}).catch(()=>{})})();